SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @ORows bigint=(SELECT ResultRows FROM lab.Evidence WHERE TableName='OrderedFact'),@SRows bigint=(SELECT ResultRows FROM lab.Evidence WHERE TableName='ShuffledFact'),@OSum bigint=(SELECT ResultSum FROM lab.Evidence WHERE TableName='OrderedFact'),@SSum bigint=(SELECT ResultSum FROM lab.Evidence WHERE TableName='ShuffledFact'),@OQ int=(SELECT QualifyingSegments FROM lab.Evidence WHERE TableName='OrderedFact'),@SQ int=(SELECT QualifyingSegments FROM lab.Evidence WHERE TableName='ShuffledFact');IF @ORows<>@SRows OR @OSum<>@SSum THROW 51006,'FAIL_RESULT_CONTRACT: Columnstore-Gegenprobe ist nicht ergebnisgleich.',1;SELECT * FROM lab.Evidence ORDER BY TableName;IF @OQ>=@SQ BEGIN PRINT 'SQLPERF_SUMMARY|WARN|WARN_EMPIRICAL_VARIANCE';RETURN;END;PRINT 'SQLPERF_SUMMARY|PASS|OK';
